INSERT INTO "blueprints" VALUES(3,'Holy Cross 30-Question Paper Matrix (Tss.pdf - 75M OBE)','GEN','OBE75','Holy Cross Autonomous Standard OBE Matrix (Q1-Q30)','Semester 1','2026-2027','Odd Semester End Examination',75,'3 Hours',NULL,'Continuous Question Numbering 1 to 30. Section B either/or pairs 21.a to 25.b.','COE_OFFICE','2026-09-24 12:00:00','2026-09-24 12:00:00','{"grid_type": "30_questions_tss", "sections": [{"name": "SECTION \u2013 A", "marks": 20, "q_range": "1-20", "formula": "20 x 1 = 20 Marks"}, {"name": "SECTION \u2013 B", "marks": 25, "q_range": "21-25", "formula": "5 x 5 = 25 Marks (Either/Or: 21.a/21.b to 25.a/25.b)"}, {"name": "SECTION \u2013 C", "marks": 20, "q_range": "26-28", "formula": "2 x 10 = 20 Marks (Answer 2 of 3)"}, {"name": "SECTION \u2013 D", "marks": 10, "q_range": "29", "formula": "1 x 10 = 10 Marks (Compulsory)"}]}');
INSERT INTO "blueprints" VALUES(4,'Holy Cross Non-OBE 50M Standard Matrix (50M Non-OBE)','GEN','NONOBE50','Holy Cross Autonomous Non-OBE Foundation & Skill Matrix','Semester 1','2026-2027','Odd Semester End Examination',50,'2 Hours',NULL,'Section A (10x1=10M), Section B (5x4=20M), Section C (2x10=20M). Total: 50 Marks.','COE_OFFICE','2026-09-24 12:00:00','2026-09-24 12:00:00','{"grid_type": "non_obe_50m", "sections": [{"name": "SECTION \u2013 A", "marks": 10, "q_range": "1-10", "formula": "10 x 1 = 10 Marks"}, {"name": "SECTION \u2013 B", "marks": 20, "q_range": "11-15", "formula": "5 x 4 = 20 Marks (Either/Or: 11.a/11.b to 15.a/15.b)"}, {"name": "SECTION \u2013 C", "marks": 20, "q_range": "16-18", "formula": "2 x 10 = 20 Marks (Answer 2 of 3)"}]}');
