INSERT INTO "generated_papers" VALUES(9,NULL,2,'U25EL1GEN01','GENERAL ENGLISH – I','ENG','Department of English','Semester 1','2025-2026','End Semester Examinations','SET A',75,'3 Hours','NOVEMBER 2026','{"institution":"HOLY CROSS COLLEGE (AUTONOMOUS)","school_name":"SCHOOL OF HUMANITIES","degree_exam_line":"I U.G. DEGREE EXAMINATION, SEMESTER-I, NOVEMBER 2026","course_part_line":"PART II - ENGLISH: GENERAL ENGLISH – I","paper_code":"U25EL1GEN01","course_title":"GENERAL ENGLISH – I","dept_name":"Department of English","dept_code":"ENG","semester":"Semester 1","academic_year":"2025-2026","exam_type":"End Semester Examinations","set_name":"SET A","duration_hours":"3 Hours","max_marks":75,"total_marks":75,"exam_date":"NOVEMBER 2026","language":"en","sections":[{"section_name":"SECTION – A","instruction":"Part I (Q.1 to 10): Multiple Choice & Part II (Q.11 to 20): Very Short Answer (20 x 1 = 20 Marks)","choice_formula":"20 x 1 = 20 Marks","total_marks":20,"questions":[{"q_number":1,"display_qno":"1","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"Explain the three passions that guide the life of Bertrand Russel as mentioned in What I Have Lived For.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":88},{"q_number":2,"display_qno":"2","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"What is Uncle Podger''s attitude towards hanging the picture in Uncle Podger Hangs a Picture?\na. Hesitant\nb. Over-confident\nc. Reluctant\nd. Disinterested","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":69},{"q_number":3,"display_qno":"3","unit_no":2,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":1,"question_text":"Complete this sentence with the correct Article:\n___ dog is playing in the yard.\na. A\nb. The\nc. An\nd. an, a","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":72},{"q_number":4,"display_qno":"4","unit_no":2,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":1,"question_text":"Explain the role of the children in transforming Giant''s character to convey the message about the importance of human connection in Oscar Wilde''s The Selfish Giant.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":99},{"q_number":5,"display_qno":"5","unit_no":3,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":1,"question_text":"The best feeling of happiness is when you are happy as you have made somebody else happy. By applying the plot of the story of Oscar Wilde''s The Selfish Giant, how would you expand your ideas in surpassing the story''s theme in changing a person who is selfish in your family?","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":91},{"q_number":6,"display_qno":"6","unit_no":3,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":1,"question_text":"Imagine you are the association representative. How would you instruct the students to gather in the auditorium for the orientation? Use common phrases to give general directions.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":85},{"q_number":7,"display_qno":"7","unit_no":4,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":1,"question_text":"Analyse the two different ways of giving directions using landmarks and street names in relation to writing sentence patterns in English for the workplace.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":95},{"q_number":8,"display_qno":"8","unit_no":4,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":1,"question_text":"Imagine a tourist asks you for directions to a famous monument in your city. Explain the best route, focusing on clarity and give other helpful details.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":94},{"q_number":9,"display_qno":"9","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"Explain how does The Sparrow reflect the concept of missed opportunities in everyday life?","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":87},{"q_number":10,"display_qno":"10","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"Narrate the story of how Uncle Podger succeeded in the task of hanging the picture as presented by Jerome K. Jerome in Uncle Podger Hangs a Picture.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":89},{"q_number":11,"display_qno":"11","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"What does the poet imply about the role of nature in human life in the poem A Patch of Land?","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":76},{"q_number":12,"display_qno":"12","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"What are the emotions and sentiments expressed by Subramania Bharati towards the land in A Patch of Land?","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":86},{"q_number":13,"display_qno":"13","unit_no":2,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":1,"question_text":"How does the grandmother show her respect for her teacher in Sudha Murthy''s How I Taught my Grandmother to Read?","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":81},{"q_number":14,"display_qno":"14","unit_no":2,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":1,"question_text":"Why did the autumn not yield fruit in the giant''s garden in The Selfish Giant?\na. A huge wall was built\nb. Plants withered\nc. No children to play\nd. No rain","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":71},{"q_number":15,"display_qno":"15","unit_no":3,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":1,"question_text":"You are in an important business meeting and get a personal emergency call from home. You are under pressure and have to leave the place immediately, apply the polite way of expression you would choose?","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":84},{"q_number":16,"display_qno":"16","unit_no":3,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":1,"question_text":"After having read the story of Sudha Murthy''s How I taught my grandmother to Read, you realise the anguish of the illiterate adults. How would you want to create an awareness with your friends and contribute something in bringing about a change in the lives of the illiterate and ways to implement Adult Education?","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":90},{"q_number":17,"display_qno":"17","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"What does the poet request from God in A Patch of Land?\na. A vast estate\nb. A small piece of land\nc. Wealth and prosperity\nd. A mansion","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":66},{"q_number":18,"display_qno":"18","unit_no":2,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":1,"question_text":"Why are the parts of speech important in a sentence?","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":82},{"q_number":19,"display_qno":"19","unit_no":3,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":1,"question_text":"Apply the grammatical rules of the parts of speech and identify the parts of speech of the italicized word in the following sentences:\n1. Sheena dances well.\n2. Ram and Sita are good friends.\n3. Oh! That was really sad.\n4. I am wearing a green dress.\n5. The teacher asked the students to stand.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":93},{"q_number":20,"display_qno":"20","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"Match the synonyms from the poem A Patch of Land in Column A with their appropriate meaning in Column B and choose the correct panel:\nColumn A:\n1. Patch\n2. Fronds\n3. Gleam\n4. Tender\nColumn B:\nA. Being soft and edible\nB. To glow and sparkle\nC. Large palm leaves with many divisions\nD. A piece of ground\na. 1A, 2B, 3C, 4D\nb. 1C, 2E, 3A, 4B\nc. 1D, 2C, 3B, 4A\nd. 1D, 2C, 3E, 4A","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":75}]},{"section_name":"SECTION – B","instruction":"Answer ALL Questions (Either/Or Type: Q.21 to Q.25) (5 x 5 = 25 Marks)","choice_formula":"5 x 5 = 25 Marks","total_marks":25,"questions":[{"q_number":21,"display_qno":"21. a","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":5,"question_text":"What happens when Uncle Podger tries to mark the spot for the nail in Uncle Podger Hangs a Picture?","answer_key":"","image_url":"","db_id":79},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":21,"display_qno":"21. b","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":5,"question_text":"List any two values of JRD Tata that helped him to succeed in aviation business according to Harish Bhat''s JRD.","answer_key":"","image_url":"","db_id":78},{"q_number":22,"display_qno":"22. a","unit_no":2,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":5,"question_text":"Discuss how passions influence one''s life decisions in choosing the right career. Provide examples from your personal life with reference to Bertrand Russel''s What I Have lived for?","answer_key":"","image_url":"","db_id":97},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":22,"display_qno":"22. b","unit_no":2,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":5,"question_text":"Explain the owl''s leadership qualities and the role of other animals in following the owl towards their own destruction with reference to the text The Owl who was God.","answer_key":"","image_url":"","db_id":98},{"q_number":23,"display_qno":"23. a","unit_no":3,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":5,"question_text":"Apply the correct punctuation to be used in the following sentences below:\n1. He is not really nice looking and yet he has enormous charm\n2. When I was a child I could watch TV whenever I wanted to\n3. It is a fine idea let us hope that it is going to work\n4. Mrs. Solomon who was sitting behind the desk gave me a big smile\n5. We were believe it or not in love with each other","answer_key":"","image_url":"","db_id":92},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":23,"display_qno":"23. b","unit_no":3,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":5,"question_text":"Applying the grammatical rules for the parts of speech identify the correct part of speech of the italicized word in the following sentence:\nSwimming is the best exercise.","answer_key":"","image_url":"","db_id":83},{"q_number":24,"display_qno":"24. a","unit_no":4,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":5,"question_text":"What did the villagers say about the scorpion sting in The Night of the Scorpion?","answer_key":"","image_url":"","db_id":77},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":24,"display_qno":"24. b","unit_no":4,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":5,"question_text":"The Sparrow addresses the theme of missed opportunities. In a busy lifestyle, personal experiences might mirror this theme by unintentionally neglecting physical and mental health. Explain how in your personal life you would have missed opportunities to care for your physical and mental health due to a busy lifestyle.","answer_key":"","image_url":"","db_id":100},{"q_number":25,"display_qno":"25. a","unit_no":5,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":5,"question_text":"What does the owl represent in the story in James Thurber''s The Owl who was a God?","answer_key":"","image_url":"","db_id":80},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":25,"display_qno":"25. b","unit_no":5,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":5,"question_text":"What is the name of Air India''s first international aircraft as mentioned in Harish Bhat''s JRD?\na. Malabar Queen\nb. Kerala Princess\nc. Kerala Kings\nd. Malabar Princess","answer_key":"","image_url":"","db_id":68}]},{"section_name":"SECTION – C","instruction":"Answer any TWO Questions (Q.26 to Q.28) (2 x 10 = 20 Marks)","choice_formula":"2 x 10 = 20 Marks","total_marks":20,"questions":[{"q_number":26,"display_qno":"26","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":10,"question_text":"What poisoned the mother in The Night of The Scorpion?\na. A snake\nb. A scorpion\nc. Acid rain\nd. Wasps","answer_key":"","image_url":"","db_id":67},{"q_number":27,"display_qno":"27","unit_no":2,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":10,"question_text":"How does the religious and cultural references contribute to the themes of the poem The Night of The Scorpion? Describe how the poem brings forth a strong sense of solidarity among the village folk of India?","answer_key":"","image_url":"","db_id":96},{"q_number":28,"display_qno":"28","unit_no":3,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":10,"question_text":"You were taught how to introduce others in a situation, so apply the techniques of introducing someone to a stranger. If you meet someone new at a conference, how will you react?\na. Ignore and walk away\nb. Wave and walk away\nc. Say, ''Hello, my name is [Your Name].''\nd. Say nothing.","answer_key":"","image_url":"","db_id":74}]},{"section_name":"SECTION – D","instruction":"Answer the following Question (Compulsory: Q.29) (1 x 10 = 10 Marks)","choice_formula":"1 x 10 = 10 Marks","total_marks":10,"questions":[{"q_number":29,"display_qno":"29","unit_no":3,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":10,"question_text":"Applying the grammatical rules of the verb, fill in the blank with the correct form of the verb in the following sentence:\nRam ---------- fast in the race.\na. Run\nb. Ran\nc. Fast\nd. In","answer_key":"","image_url":"","db_id":73}]}]}','Generated','COE_ADMIN','2026-09-24 12:19:51');
INSERT INTO "generated_papers" VALUES(10,NULL,3,'U21EC1ALT02','(Allied - 2) BUSINESS ECONOMICS','ECONOMICS','Department of Economics','Semester 1','2026-2027','Odd Semester End Examination','SET A',75,'3 Hours','NOVEMBER 2026','{"institution":"HOLY CROSS COLLEGE (AUTONOMOUS)","school_name":"SCHOOL OF HUMANITIES","degree_exam_line":"I U.G. DEGREE EXAMINATION, SEMESTER-I, NOVEMBER 2026","course_part_line":"PART III - ECONOMICS: (ALLIED - 2) BUSINESS ECONOMICS","paper_code":"U21EC1ALT02","course_title":"(Allied - 2) BUSINESS ECONOMICS","dept_name":"Department of Economics","dept_code":"ECONOMICS","semester":"Semester 1","academic_year":"2026-2027","exam_type":"Odd Semester End Examination","set_name":"SET A","duration_hours":"3 Hours","max_marks":75,"total_marks":75,"exam_date":"NOVEMBER 2026","language":"en","sections":[{"section_name":"SECTION – A","instruction":"Part I (Q.1 to 10): Multiple Choice & Part II (Q.11 to 20): Very Short Answer (20 x 1 = 20 Marks)","choice_formula":"20 x 1 = 20 Marks","total_marks":20,"questions":[{"q_number":1,"display_qno":"1","unit_no":1,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":1,"question_text":"Define the concept of ''Opportunity Cost'' and state its significance in modern managerial decision-making.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":162},{"q_number":2,"display_qno":"2","unit_no":1,"sub_unit":"1.1","k_level":"K5","co_level":"CO5","marks":1,"question_text":"Evaluate the role and responsibilities of a Business Economist in a modern competitive corporate enterprise facing market uncertainties.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":165},{"q_number":3,"display_qno":"3","unit_no":2,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":1,"question_text":"Examine the properties of Indifference Curves and explain consumer equilibrium with budget constraints.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":172},{"q_number":4,"display_qno":"4","unit_no":2,"sub_unit":"1.1","k_level":"K5","co_level":"CO5","marks":1,"question_text":"Critically assess the various degrees of Price Elasticity of Demand (Elastic, Inelastic, Unitary, Perfectly Elastic, Perfectly Inelastic) and their managerial pricing implications.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":171},{"q_number":5,"display_qno":"5","unit_no":3,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"Match the following production concepts:\n1. Short-run Production -> (a) Returns to Scale\n2. Long-run Production -> (b) Law of Variable Proportions\n3. Isoquant Slope -> (c) Marginal Rate of Technical Substitution\nChoose the correct code:\n(A) 1-(b), 2-(a), 3-(c)\n(B) 1-(a), 2-(b), 3-(c)\n(C) 1-(c), 2-(b), 3-(a)\n(D) 1-(b), 2-(c), 3-(a)","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":173},{"q_number":6,"display_qno":"6","unit_no":3,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":1,"question_text":"What are Isoquants? State their essential economic characteristics.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":174},{"q_number":7,"display_qno":"7","unit_no":4,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":1,"question_text":"Define ''Monopolistic Competition'' and give two examples of industries operating under this market structure.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":180},{"q_number":8,"display_qno":"8","unit_no":4,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":1,"question_text":"Assertion (A): Under Perfect Competition, the firm is a price taker.\nReason (R): The industry consists of a large number of buyers and sellers selling homogenous products with free entry and exit.\n(A) Both (A) and (R) are true and (R) is the correct explanation of (A)\n(B) Both (A) and (R) are true but (R) is not the correct explanation of (A)\n(C) (A) is true but (R) is false\n(D) (A) is false but (R) is true","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":179},{"q_number":9,"display_qno":"9","unit_no":5,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":1,"question_text":"A manufacturing firm has Fixed Costs of Rs. 2,00,000, Variable Cost per unit of Rs. 30, and Selling Price per unit of Rs. 50. Calculate:\n(i) Break-Even Point in units\n(ii) Margin of Safety if actual sales are 15,000 units.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":187},{"q_number":10,"display_qno":"10","unit_no":5,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":1,"question_text":"Explain Capital Budgeting and analyze the Net Present Value (NPV) method of project evaluation.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":188},{"q_number":11,"display_qno":"11","unit_no":1,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":1,"question_text":"Critically differentiate between Microeconomics and Macroeconomics from the perspective of an executive formulating firm strategy.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":164},{"q_number":12,"display_qno":"12","unit_no":1,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":1,"question_text":"Analyze the fundamental economic principles that govern managerial choices: Incremental Principle, Time Perspective, and Equi-Marginal Principle.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":166},{"q_number":13,"display_qno":"13","unit_no":2,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":1,"question_text":"Demonstrate with appropriate graphical illustration how price elasticity of demand is measured using the Point Elasticity method.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":169},{"q_number":14,"display_qno":"14","unit_no":2,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":1,"question_text":"State the Law of Demand and mention any two important exceptions to the law.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":168},{"q_number":15,"display_qno":"15","unit_no":3,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":1,"question_text":"Explain the Three Stages of the Law of Variable Proportions using a table and diagram. Identify the rational stage of production.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":175},{"q_number":16,"display_qno":"16","unit_no":3,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":1,"question_text":"Analyze the behavior of Short-Run Cost Curves (TFC, TVC, TC, AFC, AVC, AC, MC) and explain why the Long-Run Average Cost (LAC) curve is known as the Envelope Curve.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":178},{"q_number":17,"display_qno":"17","unit_no":4,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":1,"question_text":"Show how price and output are determined under Perfect Competition in the short-run equilibrium of a firm.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":181},{"q_number":18,"display_qno":"18","unit_no":4,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":1,"question_text":"Examine various Pricing Strategies adopted by modern business firms: Price Discrimination, Cost-Plus Pricing, Penetration Pricing, and Price Skimming.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":184},{"q_number":19,"display_qno":"19","unit_no":5,"sub_unit":"1.1","k_level":"K6","co_level":"CO5","marks":1,"question_text":"[Compulsory Case Study / Applied Decision Analysis]\nAn emerging electric vehicle components company is evaluating two mutually exclusive expansion capital projects:\n- Project Alpha: Initial Investment = Rs. 50 Lakhs, Annual Cash Inflow = Rs. 15 Lakhs for 5 years.\n- Project Beta: Initial Investment = Rs. 60 Lakhs, Annual Cash Inflow = Rs. 18 Lakhs for 5 years.\nAssuming a discount rate of 10% (Discount factors: Year 1=0.909, Year 2=0.826, Year 3=0.751, Year 4=0.683, Year 5=0.621), formulate an investment recommendation using NPV and Payback Period methods.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":190},{"q_number":20,"display_qno":"20","unit_no":5,"sub_unit":"1.1","k_level":"K5","co_level":"CO5","marks":1,"question_text":"Discuss the managerial utility and limitations of Break-Even Analysis. Illustrate how multi-product firms utilize Profit-Volume (P/V) ratio for profit planning.","answer_key":"","has_formula":0,"formula_latex":"","image_url":"","db_id":189}]},{"section_name":"SECTION – B","instruction":"Answer ALL Questions (Either/Or Type: Q.21 to Q.25) (5 x 5 = 25 Marks)","choice_formula":"5 x 5 = 25 Marks","total_marks":25,"questions":[{"q_number":21,"display_qno":"21. a","unit_no":1,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":5,"question_text":"Explain the scope and nature of Business Economics. How does it bridge the gap between abstract economic theory and real-world managerial practice?","answer_key":"","image_url":"","db_id":163},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":21,"display_qno":"21. b","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":5,"question_text":"Business Economics is essentially an application of economic theory to business management. Who defined economics as a study of mankind in the ordinary business of life?\n(A) Lionel Robbins\n(B) Alfred Marshall\n(C) Adam Smith\n(D) J.M. Keynes","answer_key":"","image_url":"","db_id":161},{"q_number":22,"display_qno":"22. a","unit_no":2,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":5,"question_text":"Analyze the qualitative and quantitative methods employed in Demand Forecasting for newly launched consumer durable products.","answer_key":"","image_url":"","db_id":170},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":22,"display_qno":"22. b","unit_no":2,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":5,"question_text":"When cross elasticity of demand between two goods is positive, the goods are classified as:\n(A) Complements\n(B) Substitutes\n(C) Inferior goods\n(D) Giffen goods","answer_key":"","image_url":"","db_id":167},{"q_number":23,"display_qno":"23. a","unit_no":3,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":5,"question_text":"Differentiate between Internal Economies of Scale and External Economies of Scale with real industrial examples.","answer_key":"","image_url":"","db_id":176},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":23,"display_qno":"23. b","unit_no":3,"sub_unit":"1.1","k_level":"K5","co_level":"CO5","marks":5,"question_text":"Discuss the Cobb-Douglas Production Function and explain how Returns to Scale (Increasing, Constant, Decreasing) are determined from its parameters.","answer_key":"","image_url":"","db_id":177},{"q_number":24,"display_qno":"24. a","unit_no":4,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":5,"question_text":"Analyze the Kinked Demand Curve hypothesis of Paul Sweezy to explain price rigidity under Oligopoly.","answer_key":"","image_url":"","db_id":182},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":24,"display_qno":"24. b","unit_no":4,"sub_unit":"1.1","k_level":"K5","co_level":"CO5","marks":5,"question_text":"Compare and contrast price determination and output decisions under Pure Monopoly and Monopolistic Competition.","answer_key":"","image_url":"","db_id":183},{"q_number":25,"display_qno":"25. a","unit_no":5,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":5,"question_text":"State the formula for calculating Break-Even Point (BEP) in units and in sales value.","answer_key":"","image_url":"","db_id":186},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":25,"display_qno":"25. b","unit_no":5,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":5,"question_text":"The point at which total revenue equals total cost and the firm makes neither a profit nor a loss is called:\n(A) Shut-down Point\n(B) Break-Even Point\n(C) Equilibrium Point\n(D) Optimum Output Point","answer_key":"","image_url":"","db_id":185}]},{"section_name":"SECTION – C","instruction":"Answer any TWO Questions (Q.26 to Q.28) (2 x 10 = 20 Marks)","choice_formula":"2 x 10 = 20 Marks","total_marks":20,"questions":[{"q_number":26,"display_qno":"26","unit_no":5,"sub_unit":"1.1","k_level":"K3","co_level":"CO3","marks":10,"question_text":"A manufacturing firm has Fixed Costs of Rs. 2,00,000, Variable Cost per unit of Rs. 30, and Selling Price per unit of Rs. 50. Calculate:\n(i) Break-Even Point in units\n(ii) Margin of Safety if actual sales are 15,000 units.","answer_key":"","image_url":"","db_id":187},{"q_number":27,"display_qno":"27","unit_no":5,"sub_unit":"1.1","k_level":"K2","co_level":"CO2","marks":10,"question_text":"State the formula for calculating Break-Even Point (BEP) in units and in sales value.","answer_key":"","image_url":"","db_id":186},{"q_number":28,"display_qno":"28","unit_no":4,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":10,"question_text":"Analyze the Kinked Demand Curve hypothesis of Paul Sweezy to explain price rigidity under Oligopoly.","answer_key":"","image_url":"","db_id":182}]},{"section_name":"SECTION – D","instruction":"Answer the following Question (Compulsory: Q.29) (1 x 10 = 10 Marks)","choice_formula":"1 x 10 = 10 Marks","total_marks":10,"questions":[{"q_number":29,"display_qno":"29","unit_no":1,"sub_unit":"1.1","k_level":"K4","co_level":"CO4","marks":10,"question_text":"Critically differentiate between Microeconomics and Macroeconomics from the perspective of an executive formulating firm strategy.","answer_key":"","image_url":"","db_id":164}]}]}','Generated','COE_ADMIN','2026-09-24 12:19:51');
INSERT INTO "generated_papers" VALUES(11,NULL,4,'U23TL3ALT05','காப்பிய இலக்கியமும் நாடகமும் (TAMIL LITERATURE)','TL','TAMIL','Semester 3','2026-2027','Odd Semester End Examination','SET A',75,'3 Hours','NOVEMBER 2026','{"institution":"HOLY CROSS COLLEGE (AUTONOMOUS)","school_name":"SCHOOL OF HUMANITIES","degree_exam_line":"II U.G. DEGREE EXAMINATION, SEMESTER-III, NOVEMBER 2026","course_part_line":"PART I - TAMIL: காப்பிய இலக்கியமும் நாடகமும் (TAMIL LITERATURE)","paper_code":"U23TL3ALT05","course_title":"காப்பிய இலக்கியமும் நாடகமும் (TAMIL LITERATURE)","dept_name":"TAMIL","dept_code":"TL","semester":"Semester 3","academic_year":"2026-2027","exam_type":"Odd Semester End Examination","set_name":"SET A","duration_hours":"3 Hours","max_marks":75,"total_marks":75,"exam_date":"NOVEMBER 2026","language":"ta","sections":[{"section_name":"பகுதி – அ","instruction":"பகுதி I (வினா 1-10): சரியான விடையைத் தேர்ந்தெடுத்து எழுதுக & பகுதி II (வினா 11-20): மிகக் குறுகிய விடையளி (20 x 1 = 20 மதிப்பெண்கள்)","choice_formula":"20 x 1 = 20 மதிப்பெண்கள்","total_marks":20,"questions":[{"q_number":1,"display_qno":"1","unit_no":1,"sub_unit":"1.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"சிலப்பதிகாரத்தை இயற்றியவர் யார்?\n(அ) இளங்கோவடிகள்\n(ஆ) சீத்தலைச் சாத்தனார்\n(இ) கபிலர்\n(ஈ) கம்பர்","answer_key":"(அ) இளங்கோவடிகள்","has_formula":0,"formula_latex":"","image_url":"","db_id":101},{"q_number":2,"display_qno":"2","unit_no":1,"sub_unit":"1.3","k_level":"K1","co_level":"CO1","marks":1,"question_text":"கண்ணகியின் சிலம்பு எவ்வகை மணிகளால் ஆனது?","answer_key":"மாணிக்கப் பரல்கள்","has_formula":0,"formula_latex":"","image_url":"","db_id":111},{"q_number":3,"display_qno":"3","unit_no":2,"sub_unit":"2.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"மணிமேகலை காப்பியத்தின் மையக் கருத்து யாது?\n(அ) பசிப்பிணி போக்கல்\n(ஆ) போர் புரிதல்\n(இ) வணிகம் செய்தல்\n(ஈ) அரசு ஆளுதல்","answer_key":"(அ) பசிப்பிணி போக்கல் மற்றும் அறநெறி வளர்த்தல்","has_formula":0,"formula_latex":"","image_url":"","db_id":103},{"q_number":4,"display_qno":"4","unit_no":2,"sub_unit":"2.4","k_level":"K2","co_level":"CO2","marks":1,"question_text":"மணிமேகலை துறவு பூண்டதற்கான முதன்மைக் காரணத்தைக் கூறுக.","answer_key":"உலக உயிர்களின் துயரையும் பசியையும் போக்க துறவறம் மேற்கொண்டாள்.","has_formula":0,"formula_latex":"","image_url":"","db_id":114},{"q_number":5,"display_qno":"5","unit_no":3,"sub_unit":"3.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"சீவக சிந்தாமணியின் ஆசிரியர் யார்?\n(அ) திருத்தக்கதேவர்\n(ஆ) நாதகுத்தனார்\n(இ) தோலாமொழித்தேவர்\n(ஈ) நக்கீரர்","answer_key":"(அ) திருத்தக்கதேவர்","has_formula":0,"formula_latex":"","image_url":"","db_id":105},{"q_number":6,"display_qno":"6","unit_no":3,"sub_unit":"3.3","k_level":"K1","co_level":"CO1","marks":1,"question_text":"கம்பரின் காப்பியத்திற்கு அவர் இட்ட பெயர் யாது?","answer_key":"இராமாவதாரம்","has_formula":0,"formula_latex":"","image_url":"","db_id":115},{"q_number":7,"display_qno":"7","unit_no":4,"sub_unit":"4.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"மனோன்மணீயம் நாடக நூலை எழுதியவர் யார்?\n(அ) பேராசிரியர் சுந்தரனார்\n(ஆ) பரிதிமாற்கலைஞர்\n(இ) சங்கரதாஸ் சுவாமிகள்\n(ஈ) பம்மல் சம்பந்த முதலியார்","answer_key":"(அ) பேராசிரியர் பெ. சுந்தரனார்","has_formula":0,"formula_latex":"","image_url":"","db_id":107},{"q_number":8,"display_qno":"8","unit_no":4,"sub_unit":"4.4","k_level":"K2","co_level":"CO2","marks":1,"question_text":"நாடகக் காப்பியத்தின் அங்கங்கள் எத்தனை வகைப்படும்?","answer_key":"ஐந்து நிலைகள் (தொடக்கம், வளர்ச்சி, உச்சம், வீழ்ச்சி, முடிவு)","has_formula":0,"formula_latex":"","image_url":"","db_id":118},{"q_number":9,"display_qno":"9","unit_no":5,"sub_unit":"5.1","k_level":"K1","co_level":"CO1","marks":1,"question_text":"தமிழ் நாடக தலைமை ஆசிரியர் என அழைக்கப்படுபவர் யார்?\n(அ) சங்கரதாஸ் சுவாமிகள்\n(ஆ) பரிதிமாற்கலைஞர்\n(இ) பாரதியார்\n(ஈ) பாரதிதாசன்","answer_key":"(அ) சங்கரதாஸ் சுவாமிகள்","has_formula":0,"formula_latex":"","image_url":"","db_id":109},{"q_number":10,"display_qno":"10","unit_no":5,"sub_unit":"5.4","k_level":"K2","co_level":"CO2","marks":1,"question_text":"வானொலி நாடகத்திற்கும் மேடை நாடகத்திற்கும் உள்ள முக்கிய வேறுபாடு யாது?","answer_key":"வானொலி நாடகம் ஒலி மற்றும் குரல் வழி மட்டுமே அமையும்; மேடை நாடகம் காட்சி வழி அமையும்.","has_formula":0,"formula_latex":"","image_url":"","db_id":120},{"q_number":11,"display_qno":"11","unit_no":1,"sub_unit":"1.2","k_level":"K2","co_level":"CO2","marks":1,"question_text":"மாதவியின் நடன அரங்கேற்றம் நடைபெற்ற நகர் எது?\n(அ) பூம்புகார்\n(ஆ) மதுரை\n(இ) வஞ்சி\n(ஈ) உரையூர்","answer_key":"(அ) பூம்புகார்","has_formula":0,"formula_latex":"","image_url":"","db_id":102},{"q_number":12,"display_qno":"12","unit_no":1,"sub_unit":"1.4","k_level":"K2","co_level":"CO2","marks":1,"question_text":"பாண்டிய மன்னனின் அவையில் கண்ணகி கூறிய வாதத்தை விளக்குக.","answer_key":"தன் சிலம்பில் மாணிக்கப் பரலும் அரசி சிலம்பில் முத்துப்பரலும் உள்ளதை நிரூபித்தாள்.","has_formula":0,"formula_latex":"","image_url":"","db_id":112},{"q_number":13,"display_qno":"13","unit_no":2,"sub_unit":"2.2","k_level":"K2","co_level":"CO2","marks":1,"question_text":"ஆபுத்திரனுக்கு அமுதசுரபி வழங்கியவர் யார்?\n(அ) சிந்தாதேவி\n(ஆ) தீவதிலகை\n(இ) மணிமேகலா தெய்வம்\n(ஈ) காயசண்டிகை","answer_key":"(அ) சிந்தாதேவி","has_formula":0,"formula_latex":"","image_url":"","db_id":104},{"q_number":14,"display_qno":"14","unit_no":2,"sub_unit":"2.3","k_level":"K1","co_level":"CO1","marks":1,"question_text":"அமுதசுரபியின் சிறப்பியல்பு யாது?","answer_key":"எடுக்க எடுக்க குறையாத உணவு வழங்கும் அட்சய பாத்திரம்.","has_formula":0,"formula_latex":"","image_url":"","db_id":113},{"q_number":15,"display_qno":"15","unit_no":3,"sub_unit":"3.2","k_level":"K2","co_level":"CO2","marks":1,"question_text":"கம்பராமாயணத்தில் உள்ள மொத்த காண்டங்களின் எண்ணிக்கை யாது?\n(அ) ஆறு\n(ஆ) ஏழு\n(இ) எட்டு\n(ஈ) ஐந்து","answer_key":"(அ) ஆறு காண்டங்கள்","has_formula":0,"formula_latex":"","image_url":"","db_id":106},{"q_number":16,"display_qno":"16","unit_no":3,"sub_unit":"3.4","k_level":"K2","co_level":"CO2","marks":1,"question_text":"சீவகன் மணந்த எட்டு பெண்களின் பெயர்களில் ஏதேனும் இரண்டினை எழுதுக.","answer_key":"காந்தருவதத்தை, குணமாலை, பதுமை, கேமசரி.","has_formula":0,"formula_latex":"","image_url":"","db_id":116},{"q_number":17,"display_qno":"17","unit_no":4,"sub_unit":"4.2","k_level":"K2","co_level":"CO2","marks":1,"question_text":"தமிழ் நாடகத் தந்தை என்று போற்றப்படுபவர் யார்?\n(அ) பம்மல் சம்பந்த முதலியார்\n(ஆ) சங்கரதாஸ் சுவாமிகள்\n(இ) நவாப் ராஜமாணிக்கம்\n(ஈ) டி.கே. சண்முகம்","answer_key":"(அ) பம்மல் சம்பந்த முதலியார்","has_formula":0,"formula_latex":"","image_url":"","db_id":108},{"q_number":18,"display_qno":"18","unit_no":4,"sub_unit":"4.3","k_level":"K1","co_level":"CO1","marks":1,"question_text":"மனோன்மணீயம் நாடகத்தின் கதைக்களம் எந்த நாட்டை அடிப்படையாகக் கொண்டது?","answer_key":"பாண்டிய நாடு (திருநெல்வேலி பகுதி)","has_formula":0,"formula_latex":"","image_url":"","db_id":117},{"q_number":19,"display_qno":"19","unit_no":5,"sub_unit":"5.2","k_level":"K2","co_level":"CO2","marks":1,"question_text":"நவீன நாடக அமைப்பில் ''குறியீட்டு நாடகம்'' என்பதன் இலக்கணம் யாது?\n(அ) மறைமுகப் பொருளுணர்த்துவது\n(ஆ) கேலி செய்வது\n(இ) பாட்டு மட்டும் அமைவது\n(ஈ) உரைநடை மட்டும் அமைவது","answer_key":"(அ) மறைமுகப் பொருளுணர்த்தும் உத்தி","has_formula":0,"formula_latex":"","image_url":"","db_id":110},{"q_number":20,"display_qno":"20","unit_no":5,"sub_unit":"5.3","k_level":"K1","co_level":"CO1","marks":1,"question_text":"தெருக்கூத்து நாடகத்தின் இன்றியமையாத பண்புகள் இரண்டினைக் குறிப்பிடுக.","answer_key":"கட்டியங்காரன் பாத்திரம், திறந்தவெளி அரங்கு, உரத்த பாடல் பாணி.","has_formula":0,"formula_latex":"","image_url":"","db_id":119}]},{"section_name":"பகுதி – ஆ","instruction":"அனைத்து வினாக்களுக்கும் விடையளி (எவையேனும் ஒன்று / அல்லது வகை: வினா 21 முதல் 25 வரை) (5 x 5 = 25 மதிப்பெண்கள்)","choice_formula":"5 x 5 = 25 மதிப்பெண்கள்","total_marks":25,"questions":[{"q_number":21,"display_qno":"21. a","unit_no":1,"sub_unit":"1.5","k_level":"K3","co_level":"CO3","marks":5,"question_text":"சிலப்பதிகாரம் காட்டும் பூம்புகார் நகரத்தின் சிறப்புகளை விவரிக்கவும்.","answer_key":"மருவூர்ப்பாக்கம், பட்டினப்பாக்கம், நாளங்காடி, அல்லங்காடி அமைப்புகள்.","image_url":"","db_id":121},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":21,"display_qno":"21. b","unit_no":1,"sub_unit":"1.5","k_level":"K4","co_level":"CO4","marks":5,"question_text":"சிலப்பதிகாரத்தை ''முத்தமிழ்க் காப்பியம்'' மற்றும் ''குடிமக்கள் காப்பியம்'' என அறிஞர்கள் போற்றுவதன் காரணங்களை விரிவாகக் கட்டுரைக்க.","answer_key":"இயல், இசை, நாடகம் ஒருங்கிணைந்த கட்டமைப்பு; சாதாரண குடிமக்களைத் தலைவர்களாகக் கொண்ட படைப்பு.","image_url":"","db_id":126},{"q_number":22,"display_qno":"22. a","unit_no":2,"sub_unit":"2.5","k_level":"K3","co_level":"CO3","marks":5,"question_text":"மணிமேகலையின் பாத்திரப் படைப்பில் சமூக சீர்திருத்தக் கூறுகளை ஆராய்க.","answer_key":"சிறைக் கோட்டம் அறக் கோட்டமாக மாறியமை, பசிப்பிணி ஒழிப்பு.","image_url":"","db_id":122},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":22,"display_qno":"22. b","unit_no":2,"sub_unit":"2.5","k_level":"K4","co_level":"CO4","marks":5,"question_text":"இரட்டைக் காப்பியங்கள் (சிலப்பதிகாரம் - மணிமேகலை) வெளிப்படுத்தும் சமய நல்லிணக்கம் மற்றும் அறக்கோட்பாடுகளை ஒப்பிட்டு ஆராய்க.","answer_key":"சமணம் மற்றும் பௌத்த அறங்களின் ஒப்பீடு, அறநெறி வாழ்வியல் சிந்தனைகள்.","image_url":"","db_id":127},{"q_number":23,"display_qno":"23. a","unit_no":3,"sub_unit":"3.5","k_level":"K3","co_level":"CO3","marks":5,"question_text":"கம்பனின் உவமை நயத்தினை தகுந்த சான்றுகளுடன் விளக்குக.","answer_key":"குகன் சந்திப்பு, அனுமன் வர்ணனை உவமைகள்.","image_url":"","db_id":123},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":23,"display_qno":"23. b","unit_no":3,"sub_unit":"3.5","k_level":"K4","co_level":"CO4","marks":5,"question_text":"கம்பராமாயணத்தில் வீடணன் அடைக்கலப் படலத்தின் வழியாக வெளிப்படும் கவிநயத்தையும் அறவுணர்வையும் விரித்துரைக்க.","answer_key":"அடைக்கலம் புகுந்தாரைக் காக்கும் ராமனின் உயரிய அறம் மற்றும் கவித்துவ உரையாடல்கள்.","image_url":"","db_id":128},{"q_number":24,"display_qno":"24. a","unit_no":4,"sub_unit":"4.5","k_level":"K3","co_level":"CO3","marks":5,"question_text":"மனோன்மணீயம் நாடகத்தில் குடிலனின் வஞ்சக குணத்தை வெளிக்கொணர்க.","answer_key":"அரசனைக் கவிழ்க்க குடிலன் செய்த சூழ்ச்சிகள்.","image_url":"","db_id":124},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":24,"display_qno":"24. b","unit_no":4,"sub_unit":"4.5","k_level":"K5","co_level":"CO5","marks":5,"question_text":"(கட்டாய வினா - Compulsory)\nதற்கால நவீனத் தமிழ் நாடகங்கள் எதிர்நோக்கும் சவால்களையும், அவற்றினை மீட்டெடுக்கத் தேவையான செயல்வடிவங்களையும் ஆய்ந்தறிந்து உங்கள் ஆக்கப்பூர்வமான கருத்துக்களை முன்வைக்க.","answer_key":"மின்னணு ஊடகங்களின் தாக்கம், பார்வையாளர்களை ஈர்க்கும் உத்திகள், பள்ளி/கல்லூரி அளவிலான நாடகப் பயிற்சி முறைமைகள்.","image_url":"","db_id":129},{"q_number":25,"display_qno":"25. a","unit_no":5,"sub_unit":"5.5","k_level":"K3","co_level":"CO3","marks":5,"question_text":"தமிழ் நாடக வளர்ச்சியில் சங்கரதாஸ் சுவாமிகளின் பங்களிப்பினை மதிப்பிடுக.","answer_key":"பாலர் நாடக சபை அமைத்தல், நூற்றுக்கணக்கான நாடகங்களை இயற்றி அரங்கேற்றுதல்.","image_url":"","db_id":125},{"is_or_divider":true,"display_qno":"( OR )","question_text":"( OR )"},{"q_number":25,"display_qno":"25. b","unit_no":5,"sub_unit":"5.5","k_level":"K5","co_level":"CO5","marks":5,"question_text":"நாடகக்கலையின் மூலம் சமூக விழிப்புணர்வை ஏற்படுத்தும் வழிமுறைகளை ஏதேனும் ஒரு சமகாலப் பிரச்சினையை மையமாகக் கொண்டு நாடகப் பிரதியாக உருவாக்குக.","answer_key":"சுற்றுச்சூழல் பாதுகாப்பு அல்லது கல்வி விழிப்புணர்வு குறித்த நாடகப் பிரதியமைப்பு.","image_url":"","db_id":130}]},{"section_name":"பகுதி – இ","instruction":"எவையேனும் இரண்டு வினாக்களுக்கு மட்டும் விடையளி (வினா 26 முதல் 28 வரை) (2 x 10 = 20 மதிப்பெண்கள்)","choice_formula":"2 x 10 = 20 மதிப்பெண்கள்","total_marks":20,"questions":[{"q_number":26,"display_qno":"26","unit_no":4,"sub_unit":"4.5","k_level":"K3","co_level":"CO3","marks":10,"question_text":"மனோன்மணீயம் நாடகத்தில் குடிலனின் வஞ்சக குணத்தை வெளிக்கொணர்க.","answer_key":"அரசனைக் கவிழ்க்க குடிலன் செய்த சூழ்ச்சிகள்.","image_url":"","db_id":124},{"q_number":27,"display_qno":"27","unit_no":1,"sub_unit":"1.2","k_level":"K2","co_level":"CO2","marks":10,"question_text":"மாதவியின் நடன அரங்கேற்றம் நடைபெற்ற நகர் எது?\n(அ) பூம்புகார்\n(ஆ) மதுரை\n(இ) வஞ்சி\n(ஈ) உரையூர்","answer_key":"(அ) பூம்புகார்","image_url":"","db_id":102},{"q_number":28,"display_qno":"28","unit_no":2,"sub_unit":"2.1","k_level":"K1","co_level":"CO1","marks":10,"question_text":"மணிமேகலை காப்பியத்தின் மையக் கருத்து யாது?\n(அ) பசிப்பிணி போக்கல்\n(ஆ) போர் புரிதல்\n(இ) வணிகம் செய்தல்\n(ஈ) அரசு ஆளுதல்","answer_key":"(அ) பசிப்பிணி போக்கல் மற்றும் அறநெறி வளர்த்தல்","image_url":"","db_id":103}]},{"section_name":"பகுதி – ஈ","instruction":"கட்டாய வினா (வினா 29) (1 x 10 = 10 மதிப்பெண்கள்)","choice_formula":"1 x 10 = 10 மதிப்பெண்கள்","total_marks":10,"questions":[{"q_number":29,"display_qno":"29","unit_no":3,"sub_unit":"3.5","k_level":"K3","co_level":"CO3","marks":10,"question_text":"கம்பனின் உவமை நயத்தினை தகுந்த சான்றுகளுடன் விளக்குக.","answer_key":"குகன் சந்திப்பு, அனுமன் வர்ணனை உவமைகள்.","image_url":"","db_id":123}]}]}','Generated','COE_ADMIN','2026-09-24 12:19:51');
