INSERT INTO "questions" VALUES(119,4,19,5,'SECTION-A','தெருக்கூத்து நாடகத்தின் இன்றியமையாத பண்புகள் இரண்டினைக் குறிப்பிடுக.',1,'K1','CO1',0,NULL,NULL,NULL,NULL,'2026-09-23 05:15:49','5.3',NULL,'கட்டியங்காரன் பாத்திரம், திறந்தவெளி அரங்கு, உரத்த பாடல் பாணி.','ta');
