BEGIN TRANSACTION;
CREATE TABLE answer_keys (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    course_code TEXT NOT NULL,
    question_id INTEGER DEFAULT NULL,
    bank_id INTEGER DEFAULT NULL,
    q_number INTEGER DEFAULT NULL,
    unit_no INTEGER DEFAULT 1,
    sub_unit TEXT DEFAULT '1.1',
    section_type TEXT DEFAULT 'SECTION-A',
    k_level TEXT DEFAULT 'K1',
    co_level TEXT DEFAULT 'CO1',
    answer_key TEXT NOT NULL,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE blueprints (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT,
        dept_code TEXT,
        paper_code TEXT,
        course_title TEXT,
        semester TEXT,
        academic_year TEXT,
        exam_type TEXT,
        total_marks INTEGER DEFAULT 100,
        duration_hours TEXT DEFAULT '3 Hours',
        sections_config TEXT,
        instructions TEXT,
        created_by TEXT,
        created_at TEXT,
        updated_at TEXT
    , matrix_config TEXT DEFAULT NULL);
