CREATE TABLE coe_users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE,
        password TEXT,
        name TEXT,
        role TEXT,
        department TEXT,
        created_at TEXT
    );
CREATE TABLE "courses" (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    level TEXT,
    dept_code TEXT,
    syllabus_set TEXT,
    set_year TEXT,
    programme TEXT,
    offeredby TEXT,
    coursecode TEXT,
    originalcoursecode TEXT,
    coursetype1 TEXT,
    coursetitle TEXT,
    hrs_week TEXT,
    credit TEXT,
    practical_hrs TEXT,
    coursetype TEXT,
    shortname TEXT,
    exdate_sem TEXT,
    exdate_end TEXT,
    exdate_mid TEXT,
    exdate TEXT,
    remark TEXT,
    internal1_exdate TEXT,
    internal1_sess TEXT,
    internal2_exdate TEXT,
    internal2_sess TEXT,
    sem_exdate TEXT,
    sem_sess TEXT,
    papertype TEXT,
    marktype TEXT,
    qpattern TEXT,
    maxmark TEXT,
    cmark TEXT,
    qpatternexternal TEXT,
    type TEXT
);

